+        <SeletorQuantidade valor={item.quantidade} minimo={0} tamanho="sm" desabilitado={ocupado}
+          aoMudar={aoMudarQuantidade} />
+      </div>
+      <strong className="item-sacola__valor">{reais(item.valor_final_centavos)}</strong>
+    </Cartao>
+  );
+}

