          <Aviso tom="erro">{erroInicial.mensagem}</Aviso>
        )}
      </Tela>
    );
  }
  if (!base) return <Tela titulo="Finalizar pedido"><Carregando /></Tela>;

  const carrinho = (previa ?? base).carrinho;
  const pronto = previa !== null && !calculando && previa.tipo_atendimento === tipo;
