        ...(previa.tipo_atendimento === "ENTREGA" ? [{ rotulo: "Taxa de entrega", centavos: previa.taxa_entrega_centavos }] : []),
        ...(previa.desconto_cupom_centavos > 0
          ? [{ rotulo: "Desconto (cupom)", centavos: previa.desconto_cupom_centavos, negativo: true }]
          : []),
