/* Base e moldura do app. Cores, fontes e medidas vêm de tema.css. */
*, *::before, *::after { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }
body {
  font-family: var(--fonte-base);
  font-size: var(--tam-md);
  color: var(--cor-texto);
  background: var(--cor-fundo-tela);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}
h1, h2, h3, p { margin: 0; }
button, input, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; }
:focus-visible { outline: 2px solid var(--cor-primaria); outline-offset: 2px; }

/* Coluna central com largura de celular (ERS 3.1: prioridade mobile, 390x844). */
.app {
  max-width: var(--largura-app);
  min-height: 100vh;
  margin: 0 auto;
  background: var(--cor-fundo);
  position: relative;
}

/* ---- Tela ---- */
.tela { min-height: 100vh; display: flex; flex-direction: column; }
.tela--branco { background: var(--cor-fundo); }
.tela--cinza { background: var(--cor-fundo-tela); }
.tela--com-abas { padding-bottom: calc(var(--altura-barra-nav) + var(--esp-2)); }
.tela--com-rodape { padding-bottom: calc(var(--altura-botao) + var(--esp-8)); }
.tela--com-abas.tela--com-rodape { padding-bottom: calc(var(--altura-barra-nav) + var(--altura-botao) + var(--esp-8)); }

.tela__cabecalho {
  display: flex; align-items: center; gap: var(--esp-2);
  padding: var(--esp-5) var(--esp-4) var(--esp-2);
  background: var(--cor-fundo);
  position: sticky; top: 0; z-index: 5;
}
.tela__cabecalho--aba { padding-top: var(--esp-6); }
.tela__cabecalho--aba .tela__titulo { font-size: var(--tam-2xl); }
.tela__voltar {
  border: 0; background: none; padding: var(--esp-1); margin-left: calc(-1 * var(--esp-1));
  display: inline-flex; color: var(--cor-texto);
}
.tela__titulo { font-size: var(--tam-xl); font-weight: var(--peso-titulo); }
.tela__subtitulo { font-size: var(--tam-sm); color: var(--cor-texto-suave); margin-top: 2px; }

.tela__conteudo {
  flex: 1; padding: var(--esp-3) var(--esp-4) var(--esp-6);
  display: flex; flex-direction: column; gap: var(--esp-4);
}

.tela__rodape {
  position: fixed; left: 50%; transform: translateX(-50%);
  bottom: 0; width: 100%; max-width: var(--largura-app);
  padding: var(--esp-3) var(--esp-4) var(--esp-4);
